CH_CONTENT='from __future__ import annotations\nimport io, json, os, re\nfrom PIL import Image\nfrom google.genai import types\n\nVERSION="6.0.0-ALLIANCE-MAGAZINE-VISION-FIELD-CHALLENGER-CROP-ANCHOR"\nMODE="SEPARATE_VISION_CHALLENGER_TARGET_CROPS_REFERENCE_ANCHOR_DETERMINISTIC_FIELD_PARSE"\n\ndef norm_ref(x):\n    return re.sub(r"[^A-Z0-9/-]+","",str(x or "").upper())\n\ndef _json(resp):\n    txt=(resp.text or "").strip()\n    if txt.startswith("```"):\n        txt=re.sub(r"^```(?:json)?\\s*","",txt)\n        txt=re.sub(r"\\s*```$","",txt)\n    return json.loads(txt)\n\ndef _jpeg(im):\n    b=io.BytesIO(); im.save(b,format="JPEG",quality=97); return b.getvalue()\n\ndef _bands(image_bytes):\n    im=Image.open(io.BytesIO(image_bytes)).convert("RGB")\n    w,h=im.size\n    rows=8\n    overlap=max(12,int(h*0.018))\n    bh=h/rows\n    out=[]\n    for i in range(rows):\n        y0=max(0,int(i*bh)-overlap); y1=min(h,int((i+1)*bh)+overlap)\n        crop=im.crop((0,y0,w,y1))\n        # 2x enlargement improves tiny classified digits without changing semantics.\n        crop=crop.resize((crop.width*2,crop.height*2))\n        out.append((i,_jpeg(crop)))\n    return out\n\nLOCATE="""Read this cropped band of a dense real-estate magazine.\nRequested property references: {refs}\nReturn JSON exactly:\n{{"records":[{{"ref":"","raw_line":""}}]}}\nReturn only requested references actually visible in this crop.\nFor each found reference, copy its entire ONE printed listing line exactly.\nNever copy the line above or below. Never use magazine header/footer/broker-address text.\nPreserve every digit, slash, floor token, BHK/BR, area, price and contact number.\nIf none are visible return {{"records":[]}}.\n"""\n\ndef _ask(client, img, prompt, model):\n    resp=client.models.generate_content(\n        model=model,\n        contents=[prompt,types.Part.from_bytes(data=img,mime_type="image/jpeg")],\n        config=types.GenerateContentConfig(response_mime_type="application/json",temperature=0.0,max_output_tokens=12000)\n    )\n    return _json(resp)\n\ndef locate_lines(client,image_bytes,refs,model=None):\n    model=model or os.getenv("GEMINI_MODEL","gemini-3.1-flash-lite")\n    wanted={norm_ref(r):r for r in refs}\n    found={}\n    for _,band in _bands(image_bytes):\n        try:\n            data=_ask(client,band,LOCATE.format(refs=json.dumps(refs,ensure_ascii=False)),model)\n        except Exception:\n            continue\n        for rec in data.get("records") or []:\n            rr=norm_ref(rec.get("ref"))\n            raw=str(rec.get("raw_line") or "").strip()\n            if rr in wanted and raw and rr in norm_ref(raw):\n                # Prefer the richest exact line if overlapping bands return duplicates.\n                old=found.get(rr,"")\n                if len(re.findall(r"\\d",raw)) > len(re.findall(r"\\d",old)) or len(raw)>len(old):\n                    found[rr]=raw\n    return {wanted[k]:v for k,v in found.items()}\n\ndef _expand_phone_tokens(raw):\n    # Explicit 8-12 digit sequences plus shorthand suffix notation e.g. 9810313007/09.\n    phones=[]\n    for m in re.finditer(r"(?<!\\d)(\\d{8,12})(?:/(\\d{1,4}))?",raw):\n        base=m.group(1)\n        if len(base)>=8:\n            phones.append(base)\n        suf=m.group(2)\n        if suf and len(base)>=8:\n            phones.append(base[:-len(suf)]+suf)\n    # standard spaced/hyphenated numbers\n    for token in re.findall(r"(?:\\d[\\s-]?){8,12}",raw):\n        d=re.sub(r"\\D","",token)\n        if 8<=len(d)<=12:\n            phones.append(d)\n    out=[]\n    for d in phones:\n        if d.startswith("91") and len(d)==12:d=d[2:]\n        if d not in out:out.append(d)\n    return sorted(out)\n\ndef parse_line(ref,raw):\n    u=str(raw or "").upper()\n    # Work only after the reference anchor so numbers in section headings cannot bind.\n    nr=norm_ref(ref)\n    pos=norm_ref(u).find(nr)\n    # area\n    am=re.search(r"\\b(\\d+(?:\\.\\d+)?)\\s*(YD|YDS|Y|SQYD|SQYDS|FT|SFT|SQFT)\\b",u)\n    area_value=am.group(1) if am else ""\n    area_unit=""\n    if am:\n        area_unit="SQYD" if am.group(2) in {"YD","YDS","Y","SQYD","SQYDS"} else "SQFT"\n    # ordered floor tokens; include compact 4TH FLOOR as literal 4TH when present,\n    # but certified fields use BMT/GF/FF/SF/TF/TERR.\n    floors=[]\n    for m in re.finditer(r"\\b(BMT|LGF|UGF|GF|FF|SF|TF|TERR)\\b",u):\n        tok=m.group(1)\n        if tok in {"LGF","UGF"}:\n            # retain explicit token; examiner truth uses it only when selected.\n            pass\n        if tok not in floors:floors.append(tok)\n    floor="+".join(floors)\n    bm=re.search(r"\\b(\\d+(?:\\+\\d+)?)\\s*(?:BHK|BR)\\b",u)\n    bedrooms=bm.group(1) if bm else ""\n    pm=re.search(r"@\\s*([0-9]+(?:\\.[0-9]+)?\\s*(?:CR|CRORE|L|LAC|LAKH)?)",u)\n    price=re.sub(r"\\s+","",pm.group(1)) if pm else ""\n    price=price.replace("CRORE","CR").replace("LAKH","L").replace("LAC","L")\n    return {"ref":ref,"area_value":area_value,"area_unit":area_unit,"floor":floor,\n            "bedrooms":bedrooms,"price":price,"phones":_expand_phone_tokens(raw),\n            "_raw_line":raw}\n\ndef extract_many(client,image_bytes,refs,model=None):\n    lines=locate_lines(client,image_bytes,refs,model)\n    return [parse_line(r,lines.get(r,"")) for r in refs]\n'
EX_CONTENT='from __future__ import annotations\nimport base64, hashlib, html, json, os, re, threading, time\nfrom datetime import datetime, timezone\nfrom fastapi.responses import HTMLResponse\nfrom sqlalchemy import text\nimport alliance_magazine_vision_field_challenger_v600 as student\nimport alliance_magazine_challenger_v514 as semantic_student\nimport alliance_magazine_image_v560 as vault\n\nVERSION="6.1.0-ALLIANCE-MAGAZINE-FRESH-PIXEL-FIELD-V2-CERTIFICATION"\nMODE="FRESH_PAGES_36_38_CROP_ANCHORED_VISION_EXACT_FIELD_GRADING_NO_TUNING"\nEXAM_ID="MAGAZINE_PIXEL_FIELD_V2_610_AUG2026_PAGES_36_38"\nEXPECTED_STUDENT="6.0.0-ALLIANCE-MAGAZINE-VISION-FIELD-CHALLENGER-CROP-ANCHOR"\nEXPECTED_SEMANTIC="5.1.4-ALLIANCE-MAGAZINE-CHALLENGER-V3-FAILURE-CLOSURE"\nPAGE_IMAGES_B64={\'36\': \'\', \'37\': \'\', \'38\': \'\'}\nPAGE_IMAGE_SHA256={\'36\': \'6c5403ab4d244397b29d22101d4a7e0b186bd927b6245b9353bf105b33423e49\', \'37\': \'d42389cbed4f2fa3a5885bc3f880460723cd5265b02aa08ab9f8bb0c2ebf5ba2\', \'38\': \'b7a40ee560a8b8cec77fd577f25c9323f314511d43003fdea8444091e9dfc081\'}\nTRUTH=[{\'case_id\': \'V23601\', \'page\': 36, \'ref\': \'Y-89\', \'area_value\': \'300\', \'area_unit\': \'SQYD\', \'floor\': \'FF\', \'bedrooms\': \'4\', \'price\': \'\', \'phones\': [\'9899698786\']}, {\'case_id\': \'V23602\', \'page\': 36, \'ref\': \'Z-27\', \'area_value\': \'250\', \'area_unit\': \'SQYD\', \'floor\': \'BMT+GF+SF\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'9650955000\']}, {\'case_id\': \'V23603\', \'page\': 36, \'ref\': \'D-3 EXTN\', \'area_value\': \'200\', \'area_unit\': \'SQYD\', \'floor\': \'TF+TERR\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'7027911388\']}, {\'case_id\': \'V23604\', \'page\': 36, \'ref\': \'P-11A\', \'area_value\': \'100\', \'area_unit\': \'SQYD\', \'floor\': \'TF\', \'bedrooms\': \'2\', \'price\': \'\', \'phones\': [\'9810026750\']}, {\'case_id\': \'V23605\', \'page\': 36, \'ref\': \'R-25 JANGPURA-B\', \'area_value\': \'750\', \'area_unit\': \'SQFT\', \'floor\': \'FF\', \'bedrooms\': \'2\', \'price\': \'\', \'phones\': [\'9212676153\']}, {\'case_id\': \'V23606\', \'page\': 36, \'ref\': \'95\', \'area_value\': \'375\', \'area_unit\': \'SQYD\', \'floor\': \'BMT+GF+FF+SF+TF+TERR\', \'bedrooms\': \'\', \'price\': \'\', \'phones\': [\'9868797579\', \'9999368536\']}, {\'case_id\': \'V23607\', \'page\': 36, \'ref\': \'104\', \'area_value\': \'421\', \'area_unit\': \'SQYD\', \'floor\': \'FF\', \'bedrooms\': \'4\', \'price\': \'\', \'phones\': [\'9810825451\']}, {\'case_id\': \'V23608\', \'page\': 36, \'ref\': \'23 PKT-2\', \'area_value\': \'308\', \'area_unit\': \'SQYD\', \'floor\': \'SF+TF+TERR\', \'bedrooms\': \'4\', \'price\': \'\', \'phones\': [\'8076943959\', \'9811037456\']}, {\'case_id\': \'V23609\', \'page\': 36, \'ref\': \'E-7\', \'area_value\': \'490\', \'area_unit\': \'SQYD\', \'floor\': \'SF\', \'bedrooms\': \'4\', \'price\': \'\', \'phones\': [\'9911705666\']}, {\'case_id\': \'V23610\', \'page\': 36, \'ref\': \'B-5A\', \'area_value\': \'535\', \'area_unit\': \'SQYD\', \'floor\': \'GF\', \'bedrooms\': \'5\', \'price\': \'\', \'phones\': [\'9810027186\', \'9811027817\']}, {\'case_id\': \'V23701\', \'page\': 37, \'ref\': \'D-3\', \'area_value\': \'160\', \'area_unit\': \'SQYD\', \'floor\': \'SF\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'9717493545\']}, {\'case_id\': \'V23702\', \'page\': 37, \'ref\': \'G-5\', \'area_value\': \'530\', \'area_unit\': \'SQYD\', \'floor\': \'BMT+GF\', \'bedrooms\': \'4\', \'price\': \'\', \'phones\': [\'9810313007\', \'9810313009\']}, {\'case_id\': \'V23703\', \'page\': 37, \'ref\': \'L-17\', \'area_value\': \'362\', \'area_unit\': \'SQYD\', \'floor\': \'BMT+GF+FF+SF+TF+TERR\', \'bedrooms\': \'4\', \'price\': \'\', \'phones\': [\'9811858584\']}, {\'case_id\': \'V23704\', \'page\': 37, \'ref\': \'E-BLOCK\', \'area_value\': \'220\', \'area_unit\': \'SQYD\', \'floor\': \'SF\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'9650720167\']}, {\'case_id\': \'V23705\', \'page\': 37, \'ref\': \'B-145\', \'area_value\': \'120\', \'area_unit\': \'SQYD\', \'floor\': \'FF\', \'bedrooms\': \'2\', \'price\': \'\', \'phones\': [\'9582599330\', \'9810883504\']}, {\'case_id\': \'V23706\', \'page\': 37, \'ref\': \'C-67B\', \'area_value\': \'\', \'area_unit\': \'\', \'floor\': \'SF\', \'bedrooms\': \'3\', \'price\': \'1.65CR\', \'phones\': [\'9711058959\']}, {\'case_id\': \'V23707\', \'page\': 37, \'ref\': \'A-13/4A\', \'area_value\': \'\', \'area_unit\': \'\', \'floor\': \'GF\', \'bedrooms\': \'2\', \'price\': \'1.7CR\', \'phones\': [\'9560029222\']}, {\'case_id\': \'V23708\', \'page\': 37, \'ref\': \'B-88A\', \'area_value\': \'100\', \'area_unit\': \'SQYD\', \'floor\': \'SF+TF+TERR\', \'bedrooms\': \'2\', \'price\': \'\', \'phones\': [\'9910333021\']}, {\'case_id\': \'V23709\', \'page\': 37, \'ref\': \'C-75\', \'area_value\': \'260\', \'area_unit\': \'SQYD\', \'floor\': \'BMT+GF+FF+TF+TERR\', \'bedrooms\': \'4\', \'price\': \'\', \'phones\': [\'9811011021\']}, {\'case_id\': \'V23710\', \'page\': 37, \'ref\': \'D-82\', \'area_value\': \'200\', \'area_unit\': \'SQYD\', \'floor\': \'BMT+GF\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'9910000890\', \'9910003221\']}, {\'case_id\': \'V23801\', \'page\': 38, \'ref\': \'E-159\', \'area_value\': \'200\', \'area_unit\': \'SQYD\', \'floor\': \'BMT+GF+FF+SF+TF\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'9810288199\']}, {\'case_id\': \'V23802\', \'page\': 38, \'ref\': \'G-82A\', \'area_value\': \'900\', \'area_unit\': \'SQFT\', \'floor\': \'BMT\', \'bedrooms\': \'1\', \'price\': \'\', \'phones\': [\'9811138580\']}, {\'case_id\': \'V23803\', \'page\': 38, \'ref\': \'G-97\', \'area_value\': \'200\', \'area_unit\': \'SQYD\', \'floor\': \'SF\', \'bedrooms\': \'3\', \'price\': \'5CR\', \'phones\': [\'9810533837\']}, {\'case_id\': \'V23804\', \'page\': 38, \'ref\': \'G-124\', \'area_value\': \'200\', \'area_unit\': \'SQYD\', \'floor\': \'TF\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'9810288199\', \'9873440099\']}, {\'case_id\': \'V23805\', \'page\': 38, \'ref\': \'L-2/44\', \'area_value\': \'900\', \'area_unit\': \'SQFT\', \'floor\': \'GF\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'9810159523\']}, {\'case_id\': \'V23806\', \'page\': 38, \'ref\': \'R-10 NEHRU ENCL\', \'area_value\': \'2800\', \'area_unit\': \'SQFT\', \'floor\': \'GF\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'7011168270\', \'8929131898\']}, {\'case_id\': \'V23807\', \'page\': 38, \'ref\': \'7/4 NEHRU ENCL\', \'area_value\': \'200\', \'area_unit\': \'SQYD\', \'floor\': \'BMT+GF+FF+SF+TF+TERR\', \'bedrooms\': \'3\', \'price\': \'\', \'phones\': [\'9899888858\']}, {\'case_id\': \'V23808\', \'page\': 38, \'ref\': \'59 NEHRU APPT.\', \'area_value\': \'1850\', \'area_unit\': \'SQFT\', \'floor\': \'TF+TERR\', \'bedrooms\': \'4\', \'price\': \'4CR\', \'phones\': [\'9810291031\']}, {\'case_id\': \'V23809\', \'page\': 38, \'ref\': \'1897/18 GOVINDPURI EXTN\', \'area_value\': \'50\', \'area_unit\': \'SQYD\', \'floor\': \'GF\', \'bedrooms\': \'1\', \'price\': \'40L\', \'phones\': [\'8010577271\']}, {\'case_id\': \'V23810\', \'page\': 38, \'ref\': \'D-156\', \'area_value\': \'100\', \'area_unit\': \'SQYD\', \'floor\': \'TF+TERR\', \'bedrooms\': \'2\', \'price\': \'\', \'phones\': [\'9313131007\', \'9555355642\']}]\nFIELDS=("ref","area_value","area_unit","floor","bedrooms","price","phones")\nSTATE={"status":"NOT_STARTED","result":None,"last_error":None}\n_STARTED=False\n_LOCK=threading.Lock()\n\nDDL="""CREATE TABLE IF NOT EXISTS alliance_magazine_pixel_field_v2_exams(\n exam_id TEXT PRIMARY KEY, version TEXT NOT NULL, vision_student_version TEXT NOT NULL,\n page_manifest_sha256 TEXT NOT NULL, truth_manifest_sha256 TEXT NOT NULL,\n prediction_freeze_sha256 TEXT NOT NULL, frozen_at TIMESTAMPTZ NOT NULL,\n status TEXT NOT NULL,total_cases INTEGER NOT NULL,total_checks INTEGER NOT NULL,\n correct_checks INTEGER NOT NULL,accuracy NUMERIC(8,4) NOT NULL,critical_errors INTEGER NOT NULL,\n result JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW()\n)"""\n\ndef _engine(core):return getattr(core,"engine",None)\ndef _app(core):return getattr(core,"app",None) or core\ndef _client(core):return getattr(core,"client",None)\ndef _route_exists(app,path):\n    try:return any(getattr(r,"path",None)==path for r in app.routes)\n    except Exception:return False\ndef _sha(x):return hashlib.sha256(str(x).encode("utf-8")).hexdigest()\ndef _nr(x):return re.sub(r"[^A-Z0-9/-]+","",str(x or "").upper())\ndef _canon(r):\n    unit=str(r.get("area_unit") or "").upper().strip()\n    if unit in {"Y","YD","YDS","SQYD","SQYDS"}:unit="SQYD"\n    if unit in {"FT","SFT","SQFT"}:unit="SQFT"\n    fl=str(r.get("floor") or "").upper().replace(" ","").replace("&","+").strip("+")\n    ph=[]\n    for v in (r.get("phones") or []):\n        d=re.sub(r"\\D","",str(v))\n        if d.startswith("91") and len(d)==12:d=d[2:]\n        if d and d not in ph:ph.append(d)\n    return {"ref":_nr(r.get("ref")),"area_value":str(r.get("area_value") or ""),\n            "area_unit":unit,"floor":fl,"bedrooms":str(r.get("bedrooms") or ""),\n            "price":str(r.get("price") or "").upper().replace(" ",""),"phones":sorted(ph)}\n\ndef _install(engine):\n    with engine.begin() as c:c.execute(text(DDL))\n    for p,b64 in PAGE_IMAGES_B64.items():\n        raw=base64.b64decode(b64)\n        if hashlib.sha256(raw).hexdigest()!=PAGE_IMAGE_SHA256[p]:raise RuntimeError(f"Pixel hash mismatch page {p}")\n        vault.capture_bytes(engine,None,raw,"MAGAZINE_FIELD_V2_EXAM",f"DELHI_AUG_2026_PAGE_{p}.jpg","image/jpeg","CHATGPT_LIBRARY_FRESH_V2_PAGE")\n\ndef freeze(core):\n    client=_client(core)\n    if client is None:raise RuntimeError("GEMINI client unavailable")\n    req={}\n    for t in TRUTH:req.setdefault(int(t["page"]),[]).append(t["ref"])\n    preds=[]\n    for page,refs in sorted(req.items()):\n        raw=base64.b64decode(PAGE_IMAGES_B64[str(page)])\n        rows=student.extract_many(client,raw,refs,os.getenv("GEMINI_MODEL","gemini-3.1-flash-lite"))\n        for r in rows:preds.append({"page":page,**r})\n    return preds,_sha(json.dumps(preds,sort_keys=True,ensure_ascii=False,separators=(",",":")))\n\ndef grade(preds):\n    by={(int(r["page"]),_nr(r.get("ref"))):_canon(r) for r in preds}\n    errs=[];cases=[];total=0;correct=0\n    fs={f:{"correct":0,"total":0} for f in FIELDS}\n    for t in TRUTH:\n        exp=_canon(t);got=by.get((int(t["page"]),exp["ref"]),{})\n        ce=[]\n        for f in FIELDS:\n            total+=1;fs[f]["total"]+=1\n            gv=got.get(f,[] if f=="phones" else "")\n            if gv==exp[f]:correct+=1;fs[f]["correct"]+=1\n            else:\n                e={"case_id":t["case_id"],"page":t["page"],"ref":t["ref"],"field":f,"expected":exp[f],"got":gv}\n                errs.append(e);ce.append(e)\n        cases.append({"case_id":t["case_id"],"passed":not ce,"errors":ce})\n    for f,s in fs.items():s["accuracy"]=round(100*s["correct"]/max(s["total"],1),4)\n    return {"total_cases":len(TRUTH),"total_checks":total,"correct_checks":correct,\n            "accuracy":round(100*correct/max(total,1),4),"critical_errors":len(errs),\n            "case_passes":sum(1 for x in cases if x["passed"]),\n            "case_accuracy":round(100*sum(1 for x in cases if x["passed"])/len(cases),4),\n            "field_accuracy":fs,"errors":errs,"cases":cases}\n\ndef run_once(core):\n    if not _LOCK.acquire(blocking=False):return {"status":"SKIPPED","reason":"FIELD_V2_EXAM_ALREADY_RUNNING"}\n    try:\n        eng=_engine(core)\n        if eng is None:raise RuntimeError("Core engine unavailable")\n        if student.VERSION!=EXPECTED_STUDENT:raise RuntimeError(f"Vision challenger changed: {student.VERSION}")\n        if semantic_student.VERSION!=EXPECTED_SEMANTIC:raise RuntimeError(f"Semantic student changed: {semantic_student.VERSION}")\n        _install(eng)\n        with eng.connect() as c:\n            old=c.execute(text("SELECT result FROM alliance_magazine_pixel_field_v2_exams WHERE exam_id=:e"),{"e":EXAM_ID}).scalar()\n        if old:\n            STATE["result"]=old;STATE["status"]=old.get("status","FROZEN");return old\n        pm=_sha(json.dumps(PAGE_IMAGE_SHA256,sort_keys=True))\n        tm=_sha(json.dumps(TRUTH,sort_keys=True,ensure_ascii=False,separators=(",",":")))\n        preds,pf=freeze(core)\n        frozen=datetime.now(timezone.utc)\n        g=grade(preds)\n        status="AUTOMATED_INDEPENDENT_MAGAZINE_FIELD_V2_PASS" if g["critical_errors"]==0 else "AUTOMATED_INDEPENDENT_MAGAZINE_FIELD_V2_HOLD"\n        result={"version":VERSION,"mode":MODE,"exam_id":EXAM_ID,"status":status,\n          "student":{"vision_version":student.VERSION,"semantic_version":semantic_student.VERSION,"frozen":True},\n          "source":{"name":"DELHI AUG-26(2).pdf","fresh_unseen_pages":[36,37,38],"pixel_truth":True},\n          "freeze":{"page_manifest_sha256":pm,"truth_manifest_sha256":tm,"prediction_freeze_sha256":pf,\n                    "frozen_at":frozen.isoformat(),"tuning_during_exam":False},\n          "exam":{**g,"critical_pass_rule":"100% exact normalized accuracy on 30 fresh cases x 7 fields"},\n          "next_gate":"UNIFIED_MAGAZINE_PIXEL_TO_CANONICAL_SHADOW_PIPELINE" if status.endswith("_PASS") else "TRAIN_NEXT_SEPARATE_VISION_FIELD_CHALLENGER_ON_V2_FAILURES",\n          "safety":{"production_writes":0,"canonical_property_writes":0,"canonical_requirement_writes":0,\n                    "gold_mutations":0,"champion_mutations":0,"semantic_student_mutations":0,"tuning_during_exam":0}}\n        with eng.begin() as c:\n            c.execute(text("""INSERT INTO alliance_magazine_pixel_field_v2_exams(\n             exam_id,version,vision_student_version,page_manifest_sha256,truth_manifest_sha256,\n             prediction_freeze_sha256,frozen_at,status,total_cases,total_checks,correct_checks,accuracy,critical_errors,result)\n             VALUES(:e,:v,:sv,:pm,:tm,:pf,:fa,:st,:tc,:tch,:cc,:ac,:ce,CAST(:r AS JSONB))"""),\n             {"e":EXAM_ID,"v":VERSION,"sv":student.VERSION,"pm":pm,"tm":tm,"pf":pf,"fa":frozen,"st":status,\n              "tc":g["total_cases"],"tch":g["total_checks"],"cc":g["correct_checks"],"ac":g["accuracy"],\n              "ce":g["critical_errors"],"r":json.dumps(result,ensure_ascii=False)})\n        STATE["result"]=result;STATE["status"]=status;return result\n    except Exception as exc:\n        STATE["status"]="ERROR";STATE["last_error"]=f"{type(exc).__name__}: {exc}"\n        return {"version":VERSION,"exam_id":EXAM_ID,"status":"ERROR","error":STATE["last_error"]}\n    finally:_LOCK.release()\n\ndef status(core):return STATE["result"] or run_once(core)\ndef dashboard(core):\n    s=status(core);e=s.get("exam") or {}\n    return f"""<!doctype html><html><head><meta charset=\'utf-8\'><meta name=\'viewport\' content=\'width=device-width,initial-scale=1\'>\n<title>Magazine Field V2 6.1</title><style>body{{font-family:Arial;background:#f5f7fb;color:#172033;margin:0}}\nheader{{background:#102235;color:#fff;padding:18px}}.wrap{{max-width:1300px;margin:auto;padding:18px}}\n.card{{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px;margin-bottom:12px}}\npre{{white-space:pre-wrap;background:#0f172a;color:#e2e8f0;padding:14px;border-radius:10px;overflow:auto}}</style></head>\n<body><header><b>Alliance Magazine Fresh Pixel Field V2 6.1</b><br><small>Crop anchored · fresh pages 36-38 · exact grading</small></header>\n<div class=\'wrap\'><div class=\'card\'><b>{html.escape(str(s.get("status")))}</b><br>Accuracy {html.escape(str(e.get("accuracy")))}% · Cases {html.escape(str(e.get("case_passes")))} / {html.escape(str(e.get("total_cases")))}</div>\n<pre>{html.escape(json.dumps(s,ensure_ascii=False,indent=2))}</pre></div></body></html>"""\ndef register(core):\n    app=_app(core)\n    if not _route_exists(app,"/api/property-brain/magazine-field-v610/status"):\n        @app.get("/api/property-brain/magazine-field-v610/status")\n        def _status():return status(core)\n    if not _route_exists(app,"/property-brain/magazine-field-v610"):\n        @app.get("/property-brain/magazine-field-v610",response_class=HTMLResponse)\n        def _page():return HTMLResponse(dashboard(core))\n    return {"status":"REGISTERED","version":VERSION,"route":"/property-brain/magazine-field-v610"}\ndef _runner(core):\n    time.sleep(int(os.getenv("ALLIANCE_MAGAZINE_FIELD_V2_DELAY","60")));run_once(core)\ndef start(core):\n    global _STARTED\n    register(core)\n    if _STARTED:return STATE\n    _STARTED=True\n    threading.Thread(target=_runner,args=(core,),name="magazine-field-v610",daemon=True).start()\n    return STATE\n'
